/**
 * Biểu tượng tab của trợ lý nội bộ.
 *
 * Phục vụ ngay tại cổng vào và ĐỨNG TRƯỚC bước xác thực. Không có phần này thì
 * cổng vào trả 401 cho cả /favicon.ico, trình duyệt không tải được biểu tượng và
 * hiện icon mặc định — nhìn ra khác hẳn tab của web bán hàng.
 *
 * Dùng CÙNG một ảnh với favicon của vhdcorp.com để hai tab giống hệt nhau. Ảnh
 * này vốn đã công khai trên web bán hàng nên phục vụ trước khi đăng nhập không
 * lộ thêm gì.
 */

/** PNG 64x64 — kích thước tab dùng tới. */
const ICON_64 = Buffer.from('', 'base64')

/** PNG 180x180 — biểu tượng khi lưu vào màn hình chính trên điện thoại. */
const ICON_180 = Buffer.from('', 'base64')

/** Các đường dẫn biểu tượng trình duyệt tự gọi, kèm ảnh tương ứng. */
const ICONS = new Map([
  ['/favicon.ico', ICON_64],
  ['/favicon.png', ICON_64],
  ['/favicon.svg', ICON_64],
  ['/apple-touch-icon.png', ICON_180],
  ['/apple-touch-icon-precomposed.png', ICON_180],
])

/**
 * Trả biểu tượng nếu đường dẫn là một trong các đường trình duyệt tự gọi.
 * @returns true nếu đã trả lời xong, false nếu không phải đường biểu tượng.
 */
export function serveFavicon(req, res, path) {
  const icon = ICONS.get(path)
  if (icon === undefined) return false
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.writeHead(405, { allow: 'GET, HEAD' })
    res.end()
    return true
  }
  res.writeHead(200, {
    'content-type': 'image/png',
    'content-length': String(icon.length),
    // Biểu tượng hiếm khi đổi; cho trình duyệt giữ một ngày để đỡ gọi lại
    'cache-control': 'public, max-age=86400',
  })
  res.end(req.method === 'HEAD' ? undefined : icon)
  return true
}
